function onFilterClose() {
  if (gRunningFilters) {
    const [promptTitle, promptMsg, stopButtonLabel, continueButtonLabel] =
      l10n.formatValuesSync([
        { id: "filter-running-title" },
        { id: "filter-running-message" },
        { id: "filter-stop-button" },
        { id: "filter-continue-button" },
      ]);

    const result = Services.prompt.confirmEx(
      window,
      promptTitle,
      promptMsg,
      Services.prompt.BUTTON_TITLE_IS_STRING * Services.prompt.BUTTON_POS_0 +
        Services.prompt.BUTTON_TITLE_IS_STRING * Services.prompt.BUTTON_POS_1,
      continueButtonLabel,
      stopButtonLabel,
      null,
      null,
      { value: 0 }
    );

    if (!result) {
      return false;
    }
    window.getInterface(Ci.nsIWebNavigation).stop(Ci.nsIWebNavigation.STOP_ALL);
  }

  return true;
}

function runSelectedFilters() {
  const folder =
    gRunFiltersFolder._folder || gRunFiltersFolder.selectedItem._folder;
  if (!folder) {
    return;
  }

  const filterList = MailServices.filters.getTempFilterList(folder);

  // make sure the tmp filter list uses the real filter list log stream
  filterList.loggingEnabled = gCurrentFilterList.loggingEnabled;
  filterList.logStream = gCurrentFilterList.logStream;

  let index = 0;
  for (const item of gFilterListbox.selectedItems) {
    filterList.insertFilterAt(index++, item._filter);
  }

  gRunFiltersButton.disabled = true;
  gRunningFilters = true;

  MailServices.filters.applyFiltersToFolders(
    filterList,
    [folder],
    gFilterListMsgWindow,
    {
      onStopOperation(_status) {
        gRunningFilters = false;

        // If the user closed the dialog while filters were running,
        // the DOM is destroyed. Bail out instantly to avoid Dead Object
        // exceptions and TypeErrors on null elements.
        if (window.closed) {
          return;
        }

        updateButtons();

        // Failsafe against stray status/meteor messages.
        // Once Bug 2002774 has landed, this can probably be removed.
